// Add a new field called 'myNewField' to the JSON of the item
$input.item.json.myNewField = 1;

return $input.item;

// Parse AI response and flatten the structure
const item = $input.first();
const aiResponse = item.json.message.content;

// Get the post_number from the current input data (it should be passed through)
const postNumber = item.json.post_number || 'unknown';

try {
  // Clean the response - remove thinking blocks and extract JSON
  let cleanedResponse = aiResponse.trim();

  // Remove <think>...</think> blocks (including multiline)
  cleanedResponse = cleanedResponse.replace(/<think>[\s\S]*?<\/think>\s*/gi, '');

  // Remove any markdown formatting
  if (cleanedResponse.startsWith('```json')) {
    cleanedResponse = cleanedResponse.replace(/```json\s*/, '').replace(/```\s*$/, '');
  }
  if (cleanedResponse.startsWith('```')) {
    cleanedResponse = cleanedResponse.replace(/```\s*/, '').replace(/```\s*$/, '');
  }

  // Extract JSON object - find first { and matching }
  const firstBrace = cleanedResponse.indexOf('{');
  if (firstBrace === -1) {
    throw new Error('No JSON object found in response');
  }

  let braceCount = 0;
  let jsonEnd = -1;

  for (let i = firstBrace; i < cleanedResponse.length; i++) {
    if (cleanedResponse[i] === '{') {
      braceCount++;
    } else if (cleanedResponse[i] === '}') {
      braceCount--;
      if (braceCount === 0) {
        jsonEnd = i;
        break;
      }
    }
  }

  if (jsonEnd === -1) {
    throw new Error('Incomplete JSON object found in response');
  }

  cleanedResponse = cleanedResponse.substring(firstBrace, jsonEnd + 1).trim();

  const analysis = JSON.parse(cleanedResponse);

  // Flatten the nested structure for Google Sheets
  const flattenedData = {
    post_number: postNumber,
    topic_tags: analysis.topic_tags ? analysis.topic_tags.join(', ') : '',
    // Big Five traits
    openness: analysis.big_five?.openness || 0,
    conscientiousness: analysis.big_five?.conscientiousness || 0,
    extraversion: analysis.big_five?.extraversion || 0,
    agreeableness: analysis.big_five?.agreeableness || 0,
    neuroticism: analysis.big_five?.neuroticism || 0,
    // Partner traits
    integrity_trust: analysis.partner_traits?.integrity_trust || 0,
    reliability: analysis.partner_traits?.reliability || 0,
    collaboration: analysis.partner_traits?.collaboration || 0,
    adaptability: analysis.partner_traits?.adaptability || 0,
    risk_tolerance: analysis.partner_traits?.risk_tolerance || 0,
    strategic_thinking: analysis.partner_traits?.strategic_thinking || 0,
    leadership: analysis.partner_traits?.leadership || 0,
    // Flags
    self_promotion: analysis.flags?.self_promotion || false,
    humility: analysis.flags?.humility || false,
    controversial: analysis.flags?.controversial || false,
    aggressive_language: analysis.flags?.aggressive_language || false
  };

  return [{ json: flattenedData }];

} catch (error) {
  console.error('Failed to parse AI response:', error);
  console.error('Raw response:', aiResponse);

  // Return error data with post_number
  return [{
    json: {
      post_number: postNumber,
      error: 'Failed to parse AI response',
      raw_response: aiResponse
    }
  }];
}
